INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4d0915e9229d534ac64e','AMEDEX 2025 GYNAECOLOGY (4).pdf','59','Gynaecology','A 32-year-old woman comes to your practice
because she forgot to take her 7 th and gth p
pills from a pack of OCPs containing 20mcg
ethinyloestradiol (EO) and had unprotected
intercourse on days 6 and 7. Today is the
10th day of her menstrual cycle. She wants
advice regarding contraception because she
does not want to become pregnant. Which
one of the following would be the best advice
for her?','{"A":"She should take the last missing pill\nnow and continue with the same\npack of OCP.","B":"Give emergency contraception now\nusing Postinor® (2 doses 12 hours\napart).","C":"She should take the last missed pill\nnow and continue the same OCP as\nusual and use condoms or abstain\nfor seven days.","D":"Stop the OCP, wait for four weeks,\nand check if she is pregnant.","E":"should stop taking pills from\nthe current package and Starts a\nnew one with her new period."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GYNAECOLOGY (4).pdf","supporting_pages":[59,60],"source_qid":null,"duplicate_group_id":"exact-60091b5894c7","duplicate_sources":[{"record_id":"4d0915e9229d534ac64e","record_type":"text_mcq","source_file":"AMEDEX 2025 GYNAECOLOGY (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GYNAECOLOGY (4).pdf","source_page":59,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"4d0915e9229d534ac64e","source_file":"AMEDEX 2025 GYNAECOLOGY (4).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GYNAECOLOGY (4).pdf","source_year":2025,"source_page":59,"supporting_pages":[59,60],"source_qid":null,"domain_hint":"Gynaecology","stem":"A 32-year-old woman comes to your practice\nbecause she forgot to take her 7 th and gth p\npills from a pack of OCPs containing 20mcg\nethinyloestradiol (EO) and had unprotected\nintercourse on days 6 and 7. Today is the\n10th day of her menstrual cycle. She wants\nadvice regarding contraception because she\ndoes not want to become pregnant. Which\none of the following would be the best advice\nfor her?","options":{"A":"She should take the last missing pill\nnow and continue with the same\npack of OCP.","B":"Give emergency contraception now\nusing Postin