INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('0f831f85cc46f4bd2123','AMEDEX 2025 GYNAECOLOGY (5).pdf','37','Gynaecology','e Pregnancy test (to exclude pregnancy
before first menstruation)
e Pelvic ultrasound (complementary to
physical exam)
e FSH (and LH)
e Thyroid-stimulating hormone (TSH)
e Prolactin
For exam purposes, though, one should know how
to prioritize these tests.
In the assessment of female patients with
primary amenorrhea, two critical questions
should be answered:
Are secondary sexual characteristics present or
absent?','{"A":"physical examination will evaluate secondary\nsexual characteristics such as breast development,\naxillary and pubic hair, and growth. Breasts are an\nendogenous assay for estrogen. Breast\ndevelopment consistent with a Tanner stage of II or\ngreater indicates the presence of estrogen and\novarian function (although it could be insufficient or\nprematurely failed). With breasts present, the next\nStep is always checking for the presence or\nabsence of a uterus, its anatomy, and possible\ndefects, vagina, and hymen. FHS (and LH) comes\nfirst if there is no breast development.","B":"uterus absent or present?","C":"Ultrasonography is the best method for answer!","D":"(t,''s question. Both transvaginal (if the patient |","E":"virgin) and trapsabdompaluicasopography"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GYNAECOLOGY (5).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-dd34b0e0575d","duplicate_sources":[{"record_id":"0f831f85cc46f4bd2123","record_type":"text_mcq","source_file":"AMEDEX 2025 GYNAECOLOGY (5).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GYNAECOLOGY (5).pdf","source_page":37,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"0f831f85cc46f4bd2123","source_file":"AMEDEX 2025 GYNAECOLOGY (5).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GYNAECOLOGY (5).pdf","source_year":2025,"source_page":37,"source_qid":null,"domain_hint":"Gynaecology","stem":"e Pregnancy test (to exclude pregnancy\nbefore first menstruation)\ne Pelvic ultrasound (complementary to\nphysical exam)\ne FSH (and LH)\ne Thyroid-stimulating hormone (TSH)\ne Prolactin\nFor exam purposes, though, one should know how\nto prioritize these tests.\nIn the assessment of female patients with\nprimary amenorrhea, two critical questions\nshould be answered:\nAre secondary sexual characteristics present or\nabsent?","options":{"A":"physical examination will evaluate secondary\nsexual characteristics such as breast development,\naxillary and pubic hair, and growth. Breasts are an\nendogenous assay for estrogen. Breast\ndevelopment consistent with a Tanner stage of II or\ngreater indicates the presence of estrogen and\novarian function (although it could be insufficient or\nprematurely failed). With breasts present, the next\nStep is always checking for the presence or\nabsence of a uterus, its anatomy, and possible\ndefects, vagina, and hymen. FHS (and LH) comes\nfirst if there is no breast development.","B":"uterus absent or present?","C":"Ultrasonography is the best method for answer!","D":"(t,''s question. Both transvaginal (if the patient |","E":"virgin) and trapsabdompaluicasopography"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"dd34b0e0575d5feff858f4504d79cd9b007dee5e","duplicate_group_id":"exact-dd34b0e0575d","duplicate_sources":[{"record_id":"0f831f85cc46f4bd2123","record_type":"text_mcq","source_file":"AMEDEX 2025 GYNAECOLOGY (5).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 GYNAECOLOGY (5).pdf","source_page":37,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.sou