INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('29cd832b781fb71a57f0','AMEDEX 2025 GYNAECOLOGY (5).pdf','44','Gynaecology','Kate is 22 years old and has been a patient in
your clinic for the past three years. She was
diagnosed with hypothyroidism 12 months
ago and was Started on levothyroxine 100
mcg daily. Today, she has presented with
complaints of hot flashes and irregular
periods for the past four months. Her periods
