INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f0995835a33f3d17d0cc','AMEDEX 2025 HEMAETOLOGY (2).pdf','34','Mixed/Unclassified','Joseph, five years old, is brought to the
emergency department by his mother. About
one hour ago, while running at home, he
hit his face against the coffee table and hada
nosebleed. The mother tried to stop the
bleeding by compressing the nose and
applying ice, to no avail. On physical
examination, the child looks
otherwise healthy with no remarkable
finding. A full blood exam (FBE) is
inconclusive. Which one of the following
could be the most likely cause of this
