INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a8a1d7a6d17d62e8ed48','AMEDEX 2025 HEMAETOLOGY (2).pdf','73','Haematology/Gastroenterology','A 22-year-old man presents with complaints of weakness and lethargy for the past few months. He denies abdominal pain, rectal bleeding, or bowel symptoms. His past medical history is not remarkable. A full blood examination and iron studies show severe microcytic anaemia with low ferritin and low serum iron. Which one of the following options is most likely to help reach a diagnosis?',NULL,'D','Option D Is correct

According to WHO, anemia is defined as
hemoglobin (Hb) <120 g/L for females and <130
g/L for men. According to the Royal College of
Pathologists of Australasia, iron deficiency is
present when the serum ferritin level is less than
30 yg/L for an adult. Therefore, this patient has
iron deficiency anemia. lron deficiency is never a
final diagnosis in itself and a cause should always
be sought.

The most common cause of iron deficiency is
ongoing bleeding, either overt (e.g., heavy periods,
or occult such as that occurring in gastrointestinal
bleeding or malignancies). In cases with confirmed
iron deficiency anemia for which an obvious source
of blood loss cannot be identified in history or
physical examination, upper and lower
gastrointestinal investigations should be
considered. In fact, upper and lower
gastrointestinal tract scope is mandatory in all
postmenopausal females and all males with
confirmed iron deficiency anemia unless there Is a
history of significant overt non-GI blood loss such

as vaginal bleeding.

In premenopausal women with iron deficiency
anemia, upper and lower gastrointestinal (Gl)
investigation should be reserved for those age

over 50 years who have symptoms suggestive

Gl disease Or auatremeutenstyninetemeof Colorectal

In premenopausal women with iron deficiency

anemia, upper and lower gastrointestinal (Gl)
investigation should be reserved for those aged
over 50 years who have symptoms suggestive of
Gl disease or a strong family history of colorectal

Cancer.

This patient is a male with iron deficiency anemia.
Since there is no apparent cause for the blood
loss, and since the GI tract is the most common
site of occult blood loss in such patients, the first
and most important step to consider is GI
investigations starting with a colonoscopy. If no
identifiable is found in colonoscopy, upper
endoscopy should follow. Sigmoidoscopy (option
E) is not an appropriate choice for this purpose
because it only provides information about the
Sigmoid colon and will miss more proximal

potential sources of bleeding.

Celiac disease should also be considered a
differential diagnosis and excluded in all patients
with iron deficiency anemia using serologic studies.
These tests are screening tests, and those with
positive test results will require a small bowel
biopsy (option B) as the confirmatory test. Not
every patient with iron deficiency anemia

undergoes a small bowel biopsy.

(Option A) Bone marrow biopsy and aspiration
may be used for many conditions, such as
leukopenia, leukocytosis, thrombocytopenia,

thrombocytosis, pancytopenia, and polycythe
This test would be used if anemia could not be

justified by irorPOStttehey~ ori tiie patient, besides','{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 HEMAETOLOGY (2).pdf","supporting_pages":[73,74,75,76,77],"source_qid":null,"duplicate_group_id":null,"duplicate_sources":[],"parser_version":"manual-review-batch008-2026-09-24","parser_mode":"human_visual_review_batch008","text_method":"manual_visual_plus_context","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"a8a1d7a6d17d62e8ed48","record_type":"text_mcq","source_file":"AMEDEX 2025 HEMAETOLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 HEMAETOLOGY (2).pdf","source_year":2025,"source_page":73,"supporting_pages":[73,74,75,76,77],"source_qid":null,"domain_hint":"Haematology/Gastroenterology","stem":"A 22-year-old man presents with complaints of weakness and lethargy for the past few months. He denies abdominal pain, rectal bleeding, or bowel symptoms. His past medical history is not remarkable. A full blood examination and iron studies show severe microcytic anaemia with low ferritin and low serum iron. Which one of the following options is most likely to help reach a diagnosis?","options":{},"options_mode":"text","source_answer":"D","source_explanation":"Option D Is correct\n\nAccording to WHO, anemia is defined as\nhemoglobin (Hb) <120 g/L for females and <130\ng/L for men. According to the Royal College of\nPathologists of Australasia, iron deficiency is\npresent when the serum ferritin level is less than\n30 yg/L for an adult. Therefore, this patient has\niron deficiency anemia. lron deficiency is never a\nfinal diagnosis in itself and a cause should always\nbe sought.\n\nThe most common cause of iron deficiency is\nongoing bleeding, either overt (e.g., heavy periods,\nor occult such as that occurring in gastrointestinal\nbleeding or malignancies). In cases with confirmed\niron deficiency anemia for which an obvious source\nof blood loss cannot be identified in hi