INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('54972d338f22c52eee1d','AMEDEX 2025 HEMAETOLOGY (2).pdf','79','Mixed/Unclassified','A 67-year-old man is brought to the
emergency department with sudden-onset
severe headache and confusion. He was
diagnosed with atrial fibrillation (AF)
four months ago, for which he has been on
warfarin since then. Blood studies show an
INR of 3.5. A CT scan of the head reveals
intracerebral hemorrhage. Which one of the
following is the most appropriate next step in
