INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3f7d7a0947aadbb2e1c0','AMEDEX 2025 HEMAETOLOGY (2).pdf','94','Mixed/Unclassified','A 54-year-old man from India presents to
your clinic with tiredness and fatigue for the
past 12 months. He is a Strict vegetarian. He
does not consume alcohol or smoke. He
denies abdominal symptoms. On
examination, he is very pale. The rest of the
examination is unremarkable. Blood tests
show a low hemoglobin (90 g/L) and an MCV
of 130 fL (normal 76-96 fL). Which one of the
following is the most likely cause of his
presentation?','{"A":"Folic acid deficiency.","B":"Thalassemia.","C":"Vitamin B12 deficiency.","D":"Lead poisoning.","E":"lron deficiency."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 HEMAETOLOGY (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-62e6aa79c701","duplicate_sources":[{"record_id":"3f7d7a0947aadbb2e1c0","record_type":"text_mcq","source_file":"AMEDEX 2025 HEMAETOLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 HEMAETOLOGY (2).pdf","source_page":94,"source_qid":null},{"record_id":"9fa21d190e8e0f3334ce","record_type":"text_mcq","source_file":"AMEDEX 2025 HEMAETOLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 HEMAETOLOGY (2).pdf","source_page":95,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"3f7d7a0947aadbb2e1c0","source_file":"AMEDEX 2025 HEMAETOLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 HEMAETOLOGY (2).pdf","source_year":2025,"source_page":94,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 54-year-old man from India presents to\nyour clinic with tiredness and fatigue for the\npast 12 months. He is a Strict vegetarian. He\ndoes not consume alcohol or smoke. He\ndenies abdominal symptoms. On\nexamination, he is very pale. The rest of the\nexamination is unremarkable. Blood tests\nshow a low hemoglobin (90 g/L) and an MCV\nof 130 fL (normal 76-96 fL). Which one of the\nfollowing is the most likely cause of his\npresentation?","options":{"A":"Folic acid deficiency.","B":"Thalassemia.","C":"Vitamin B12 deficiency.","D":"Lead poisoning.","E":"lron deficiency."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_ver