INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('324e1f87a107b3d8e5ab','AMEDEX 2025 HEMAETOLOGY (2).pdf','135','Mixed/Unclassified','A 69-year-old woman has been in the
Intensive Care Unit (ICU) for the past
seven days following a complicated hip
replacement surgery. She is currently on low-
molecular-weight heparin (LMWH) as well as
an intermittent pneumatic compression
device. Today, she has developed new-onset
right calf pain. On examination, the leg is
edematous and tender to touch. A positive
Homan’s sign is elicited. A Doppler ultrasound
confirms the presence of a clot in the right
lower leg and the diagnosis of deep vein
thrombosis. Blood tests show a platelet count
of 78,000 /mm, but there is no sign of
hemorrhage. Which one of the following is
